<?php
if(!defined('ABSPATH')){exit;}
final class Orion_Manager_Queue_Admin{
 private Orion_Conversation_Service $conversations;private Orion_Knowledge_Base $knowledge;private Orion_Manager_Handoff $gaps;
 public function __construct(Orion_Conversation_Service $conversations,Orion_Knowledge_Base $knowledge){$this->conversations=$conversations;$this->knowledge=$knowledge;$this->gaps=new Orion_Manager_Handoff();}
 public function register():void{add_action('admin_post_orion_ai_update_gap',array($this,'handle_update'));add_action('admin_post_orion_ai_update_improvement_ticket',array($this,'handle_ticket'));}
 public function render():void{if(!current_user_can('manage_woocommerce'))return;$selected=absint($_GET['gap_id']??0);$status=sanitize_key(wp_unslash($_GET['gap_status']??''));$reason=sanitize_key(wp_unslash($_GET['gap_reason']??''));$type=sanitize_key(wp_unslash($_GET['gap_type']??''));$group=absint($_GET['gap_group']??0);$per_page=absint($_GET['gap_per_page']??10);if(!in_array($per_page,array(10,20,50),true))$per_page=10;$page=max(1,absint($_GET['gap_page']??1));$filters=array();if(Orion_Manager_Queue_Policy::is_status($status))$filters['status']=$status;if($reason!=='')$filters['reason_code']=$reason;if(in_array($type,Orion_Improvement_Ticket_Policy::types(),true))$filters['gap_type']=$type;if($group)$filters['gap_group_id']=$group;$item=$selected?$this->gaps->get($selected):null;$total=$item?1:$this->gaps->total($filters);$pages=max(1,(int)ceil($total/$per_page));$page=min($page,$pages);$items=$item?array($item):$this->gaps->all($per_page,$filters,($page-1)*$per_page);echo '<section class="orion-card orion-gaps"><h2>AI improvement gaps</h2><p>Repeated requests are grouped into one internal improvement ticket. Tickets organise verified work only; they never automatically publish knowledge, edit products, change routing or answer a customer.</p>';$this->counts($status);if(!$selected)$this->repeated_groups($group);if($group&&!$selected)$this->ticket($group);$this->filters($status,$reason,$type,$group,$per_page);if($selected)echo '<p><a href="'.esc_url(add_query_arg(array('page'=>'orion-ai-assistant','tab'=>'gaps'),admin_url('admin.php'))).'">← Back to all gaps</a></p>';else$this->pagination($page,$per_page,$total,$filters);if(!$items)echo '<p>No improvement gaps match these filters.</p>';foreach($items as$row)$this->item($row);if(!$selected)$this->pagination($page,$per_page,$total,$filters);echo '</section><style>.orion-admin .orion-gaps{max-width:1200px}.orion-gap-counts{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0}.orion-gap-count{padding:7px 11px;border:1px solid #c3c4c7;border-radius:999px;background:#fff;text-decoration:none}.orion-gap-count.is-active{border-color:#2271b1;background:#f0f6fc}.orion-gap-groups,.orion-ticket{margin:18px 0;padding:14px;border:1px solid #dcdcde;border-radius:8px;background:#fff}.orion-gap-groups h3,.orion-ticket h3{margin-top:0}.orion-ticket{border-left:5px solid #2271b1}.orion-ticket-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.orion-ticket-grid .wide{grid-column:1/-1}.orion-ticket label{display:grid;gap:4px}.orion-ticket textarea{width:100%;min-height:100px}.orion-ticket-meta{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.orion-gap-filters{display:flex;gap:12px;align-items:end;flex-wrap:wrap;padding:14px;background:#f6f7f7;border:1px solid #dcdcde;border-radius:8px}.orion-gap-filters label{display:grid;gap:4px}.orion-gap-pagination{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin:18px 0}.orion-gap-pagination .page-numbers{display:flex;gap:4px;align-items:center;margin:0}.orion-gap-pagination .page-numbers li{margin:0}.orion-gap-pagination .page-numbers a,.orion-gap-pagination .page-numbers span{display:inline-block;min-width:30px;padding:5px 8px;text-align:center;border:1px solid #c3c4c7;border-radius:4px;text-decoration:none;background:#fff}.orion-gap-pagination .page-numbers .current{background:#2271b1;border-color:#2271b1;color:#fff}.orion-gap{margin-top:16px;padding:18px;border:1px solid #dcdcde;border-left:5px solid #dba617;border-radius:8px;background:#fff}.orion-gap.is-resolved{border-left-color:#00a32a}.orion-gap.is-dismissed{border-left-color:#787c82}.orion-gap-meta{display:flex;gap:8px;flex-wrap:wrap}.orion-gap-badge{display:inline-block;padding:3px 8px;border-radius:999px;background:#f0f0f1;font-size:12px}.orion-gap-type{background:#e7f2fa;color:#135e96}.orion-gap-repeat{background:#fcf0d8;color:#6f4f00}.orion-gap-action{margin:14px 0;padding:12px 14px;border-left:4px solid #2271b1;background:#f0f6fc}.orion-gap-form{display:grid;gap:12px;margin-top:16px;padding-top:16px;border-top:1px solid #eee}.orion-gap-form textarea{width:100%;min-height:120px}.orion-gap-actions{display:flex;gap:8px;flex-wrap:wrap}@media(max-width:782px){.orion-ticket-grid{grid-template-columns:1fr}.orion-ticket-grid .wide{grid-column:auto}}</style>';}
 private function counts(string $active):void{$counts=$this->gaps->counts();echo '<div class="orion-gap-counts">';$this->count_link('','All',array_sum($counts),$active==='');foreach(Orion_Manager_Queue_Policy::statuses()as$status)$this->count_link($status,$this->status_label($status),(int)($counts[$status]??0),$active===$status);echo '</div>';}
 private function count_link(string $status,string $label,int $count,bool $active):void{$args=array('page'=>'orion-ai-assistant','tab'=>'gaps');if($status!=='')$args['gap_status']=$status;echo '<a class="orion-gap-count '.($active?'is-active':'').'" href="'.esc_url(add_query_arg($args,admin_url('admin.php'))).'">'.esc_html($label).' <strong>'.$count.'</strong></a>';}
 private function repeated_groups(int $active):void{$groups=$this->gaps->groups(20,2);if(!$groups)return;echo '<div class="orion-gap-groups"><h3>Repeated gap groups and tickets</h3><p class="description">One group can have one internal ticket. Priority is suggested from repetition but remains manager-controlled.</p><table class="widefat striped"><thead><tr><th>Group</th><th>Type</th><th>Representative request</th><th>Occurrences</th><th>Open</th><th>Ticket</th><th>Priority</th><th></th></tr></thead><tbody>';foreach($groups as$row){$id=(int)$row['id'];$created=!empty($row['ticket_created_at']);$status=$created?Orion_Improvement_Ticket_Policy::ticket_status_label((string)$row['ticket_status']):'No ticket';$priority=$created?Orion_Improvement_Ticket_Policy::priority_label((string)$row['ticket_priority']):Orion_Improvement_Ticket_Policy::priority_label(Orion_Improvement_Ticket_Policy::suggested_priority((int)$row['occurrence_count'],(int)$row['open_count'])).' suggested';$url=add_query_arg(array('page'=>'orion-ai-assistant','tab'=>'gaps','gap_group'=>$id),admin_url('admin.php'));echo '<tr'.($active===$id?' class="is-active"':'').'><td>#'.$id.'</td><td>'.esc_html(Orion_Improvement_Ticket_Policy::label((string)$row['gap_type'])).'</td><td>'.esc_html(mb_substr((string)$row['representative_question'],0,120)).'</td><td><strong>'.(int)$row['occurrence_count'].'</strong></td><td>'.(int)$row['open_count'].'</td><td>'.esc_html($status).'</td><td>'.esc_html($priority).'</td><td><a class="button button-small" href="'.esc_url($url).'">'.($created?'Open ticket':'Create ticket').'</a></td></tr>';}echo '</tbody></table></div>';}
 private function ticket(int $group_id):void{$group=$this->gaps->get_group($group_id);if(!$group){echo '<div class="notice notice-error inline"><p>Improvement group not found.</p></div>';return;}$created=!empty($group['ticket_created_at']);$status=$created?Orion_Improvement_Ticket_Policy::normalize_ticket_status((string)$group['ticket_status']):Orion_Improvement_Ticket_Policy::TICKET_BACKLOG;$priority=$created?Orion_Improvement_Ticket_Policy::normalize_priority((string)$group['ticket_priority']):Orion_Improvement_Ticket_Policy::suggested_priority((int)$group['occurrence_count'],(int)$group['open_count']);$title=(string)($group['ticket_title']??'');if(!$created&&$title==='')$title='Improve '.Orion_Improvement_Ticket_Policy::label((string)$group['gap_type']).': '.mb_substr((string)($group['topic']?:$group['representative_question']),0,120);$owner=absint($group['ticket_owner_id']??0);if(!$created)$owner=get_current_user_id();$users=get_users(array('capability'=>'manage_woocommerce','orderby'=>'display_name','order'=>'ASC'));echo '<div class="orion-ticket"><h3>'.($created?'Improvement ticket for group #':'Create improvement ticket for group #').$group_id.'</h3><div class="orion-ticket-meta"><span class="orion-gap-badge orion-gap-type">'.esc_html(Orion_Improvement_Ticket_Policy::label((string)$group['gap_type'])).'</span><span class="orion-gap-badge orion-gap-repeat">'.(int)$group['occurrence_count'].' occurrences</span><span class="orion-gap-badge">'.(int)$group['open_count'].' open</span>';if($created)echo '<span class="orion-gap-badge">'.esc_html(Orion_Improvement_Ticket_Policy::ticket_status_label($status)).'</span>';echo '</div><p><strong>Recommended source action:</strong> '.esc_html(Orion_Improvement_Ticket_Policy::recommended_action((string)$group['gap_type'])).'</p><p class="description">Saving this ticket does not change any linked gap or customer response. Resolution requires written verification evidence.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('orion_ai_update_improvement_ticket_'.$group_id);echo '<input type="hidden" name="action" value="orion_ai_update_improvement_ticket"><input type="hidden" name="group_id" value="'.$group_id.'"><div class="orion-ticket-grid"><label class="wide"><strong>Ticket title</strong><input class="widefat" name="ticket_title" maxlength="240" required value="'.esc_attr($title).'"></label><label><strong>Status</strong><select name="ticket_status">';foreach(Orion_Improvement_Ticket_Policy::ticket_statuses()as$value){$allowed=!$created?$value===Orion_Improvement_Ticket_Policy::TICKET_BACKLOG:Orion_Improvement_Ticket_Policy::can_ticket_transition($status,$value);if($allowed)echo '<option value="'.esc_attr($value).'" '.selected($status,$value,false).'>'.esc_html(Orion_Improvement_Ticket_Policy::ticket_status_label($value)).'</option>';}echo '</select></label><label><strong>Priority</strong><select name="ticket_priority">';foreach(Orion_Improvement_Ticket_Policy::ticket_priorities()as$value)echo '<option value="'.esc_attr($value).'" '.selected($priority,$value,false).'>'.esc_html(Orion_Improvement_Ticket_Policy::priority_label($value)).'</option>';echo '</select></label><label><strong>Owner</strong><select name="ticket_owner_id"><option value="0">Unassigned</option>';foreach($users as$user)echo '<option value="'.(int)$user->ID.'" '.selected($owner,(int)$user->ID,false).'>'.esc_html($user->display_name).'</option>';echo '</select></label><label><strong>Reference URL</strong><input class="widefat" type="url" name="ticket_reference_url" value="'.esc_attr((string)($group['ticket_reference_url']??'')).'"></label><label class="wide"><strong>Fix plan</strong><textarea name="ticket_plan" minlength="10" maxlength="12000" required>'.esc_textarea((string)($group['ticket_plan']??'')).'</textarea><span class="description">Describe the approved change location: Knowledge Base, WooCommerce data, routing/provider configuration or code.</span></label><label class="wide"><strong>Verification evidence</strong><textarea name="ticket_verification" maxlength="12000">'.esc_textarea((string)($group['ticket_verification']??'')).'</textarea><span class="description">Required before moving from Validating to Resolved. Record the regression case, trace, product check or policy answer used to verify the fix.</span></label></div><p><button class="button button-primary">'.($created?'Save ticket':'Create ticket').'</button></p></form>';$history=$this->gaps->ticket_history($group_id,30);if($history){echo '<details><summary>Ticket history</summary><ul>';foreach($history as$event){$uid=absint($event['user_id']??0);$user=$uid?get_userdata($uid):false;$actor=$user?$user->display_name:($uid?'User #'.$uid:'System');echo '<li><strong>'.esc_html(str_replace('_',' ',(string)$event['event_type'])).'</strong> · '.esc_html($actor).' · '.esc_html((string)$event['created_at']).'</li>';}echo '</ul></details>';}echo '</div>';}
 private function filters(string $status,string $reason,string $type,int $group,int $per_page):void{$reasons=$this->gaps->reason_counts();$types=$this->gaps->type_counts();echo '<form class="orion-gap-filters" method="get" action="'.esc_url(admin_url('admin.php')).'"><input type="hidden" name="page" value="orion-ai-assistant"><input type="hidden" name="tab" value="gaps">';if($group)echo '<input type="hidden" name="gap_group" value="'.$group.'"><strong>Group #'.$group.'</strong>';echo '<label><strong>Status</strong><select name="gap_status"><option value="">All statuses</option>';foreach(Orion_Manager_Queue_Policy::statuses()as$value)echo '<option value="'.esc_attr($value).'" '.selected($status,$value,false).'>'.esc_html($this->status_label($value)).'</option>';echo '</select></label><label><strong>Improvement type</strong><select name="gap_type"><option value="">All types</option>';foreach(Orion_Improvement_Ticket_Policy::types()as$value)echo '<option value="'.esc_attr($value).'" '.selected($type,$value,false).'>'.esc_html(Orion_Improvement_Ticket_Policy::label($value)).' ('.(int)($types[$value]??0).')</option>';echo '</select></label><label><strong>Reason</strong><select name="gap_reason"><option value="">All reasons</option>';foreach($reasons as$row){$value=(string)$row['reason_code'];echo '<option value="'.esc_attr($value).'" '.selected($reason,$value,false).'>'.esc_html(str_replace('_',' ',$value)).' ('.(int)$row['total'].')</option>';}echo '</select></label><label><strong>Per page</strong><select name="gap_per_page">';foreach(array(10,20,50)as$value)echo '<option value="'.$value.'" '.selected($per_page,$value,false).'>'.$value.'</option>';echo '</select></label><button class="button">Apply</button><a class="button" href="'.esc_url(add_query_arg(array('page'=>'orion-ai-assistant','tab'=>'gaps'),admin_url('admin.php'))).'">Reset</a></form>';}
 private function pagination(int $page,int $per_page,int $total,array $filters):void{if($total<1)return;$first=(($page-1)*$per_page)+1;$last=min($total,$page*$per_page);$pages=max(1,(int)ceil($total/$per_page));$args=array('page'=>'orion-ai-assistant','tab'=>'gaps','gap_per_page'=>$per_page);if(isset($filters['status']))$args['gap_status']=$filters['status'];if(isset($filters['reason_code']))$args['gap_reason']=$filters['reason_code'];if(isset($filters['gap_type']))$args['gap_type']=$filters['gap_type'];if(isset($filters['gap_group_id']))$args['gap_group']=$filters['gap_group_id'];$args['gap_page']='%#%';$base=str_replace('%25%23%25','%#%',add_query_arg($args,admin_url('admin.php')));$links=$pages>1?paginate_links(array('base'=>$base,'format'=>'','current'=>$page,'total'=>$pages,'mid_size'=>2,'end_size'=>1,'prev_text'=>'‹','next_text'=>'›','type'=>'list')):'';echo '<nav class="orion-gap-pagination" aria-label="Improvement gap pages"><span>Showing '.(int)$first.'–'.(int)$last.' of '.(int)$total.'</span>'.($links?$links:'').'</nav>';}
 private function item(array $item):void{$id=(int)$item['id'];$status=(string)$item['status'];$type=Orion_Improvement_Ticket_Policy::normalize((string)($item['gap_type']??''));$group_id=absint($item['gap_group_id']??0);$occurrences=max(1,absint($item['group_occurrence_count']??1));$trace=absint($item['trace_id']??0);$conversation=absint($item['conversation_id']??0);$context=json_decode((string)($item['context_json']??''),true);$context=is_array($context)?$context:array();echo '<article class="orion-gap is-'.esc_attr($status).'"><div style="display:flex;justify-content:space-between;gap:16px"><div><h3 style="margin:0">Improvement gap #'.$id.'</h3><div class="orion-gap-meta"><span class="orion-gap-badge">'.esc_html($this->status_label($status)).'</span><span class="orion-gap-badge orion-gap-type">'.esc_html(Orion_Improvement_Ticket_Policy::label($type)).'</span><span class="orion-gap-badge">'.esc_html(str_replace('_',' ',(string)$item['reason_code'])).'</span>';if($group_id){$group_url=add_query_arg(array('page'=>'orion-ai-assistant','tab'=>'gaps','gap_group'=>$group_id),admin_url('admin.php'));echo '<a class="orion-gap-badge orion-gap-repeat" href="'.esc_url($group_url).'">Group #'.$group_id.' · '.$occurrences.' occurrence'.($occurrences===1?'':'s').'</a>';}echo '</div></div><small>'.esc_html((string)$item['created_at']).'</small></div><p style="font-size:15px;line-height:1.55">'.nl2br(esc_html((string)$item['question'])).'</p><div class="orion-gap-action"><strong>Recommended action</strong><br>'.esc_html(Orion_Improvement_Ticket_Policy::recommended_action($type));if(in_array($type,array(Orion_Improvement_Ticket_Policy::TYPE_CATALOGUE,Orion_Improvement_Ticket_Policy::TYPE_PRODUCT_DATA),true))echo '<p><a class="button button-small" href="'.esc_url(admin_url('edit.php?post_type=product')).'">Open WooCommerce products</a></p>';echo '</div><p>';$conversation_url=add_query_arg(array('page'=>'orion-ai-assistant','tab'=>'conversations','conversation_id'=>$conversation),admin_url('admin.php'));echo '<a class="button button-small" href="'.esc_url($conversation_url).'">Open full conversation #'.$conversation.'</a> ';if($trace){$trace_url=add_query_arg(array('page'=>'orion-ai-assistant','tab'=>'traces','trace_id'=>$trace),admin_url('admin.php'));echo '<a class="button button-small" href="'.esc_url($trace_url).'">Open trace #'.$trace.'</a>';}echo '</p>';if($context)echo '<details><summary>Diagnostic context</summary><pre style="white-space:pre-wrap;max-height:360px;overflow:auto">'.esc_html(wp_json_encode($context,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)).'</pre></details>';if(!empty($item['knowledge_document_id']))echo '<div class="notice notice-success inline"><p>Added to Knowledge Base as document #'.(int)$item['knowledge_document_id'].' on '.esc_html((string)$item['knowledge_published_at']).'.</p></div>';$this->form($item,$type);$this->history($id);echo '</article>';}
 private function form(array $item,string $type):void{$id=(int)$item['id'];$status=(string)$item['status'];$knowledge=Orion_Improvement_Ticket_Policy::can_publish_to_knowledge($type);echo '<form class="orion-gap-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('orion_ai_update_gap_'.$id);echo '<input type="hidden" name="action" value="orion_ai_update_gap"><input type="hidden" name="gap_id" value="'.$id.'">';$this->return_fields();echo '<label><strong>'.($knowledge?'Knowledge title':'Improvement title').'</strong><input class="widefat" maxlength="240" name="knowledge_title" value="'.esc_attr((string)($item['knowledge_title']??'')).'"></label><label><strong>'.($knowledge?'Verified guidance':'Review notes and evidence').'</strong><textarea name="verified_guidance" maxlength="12000">'.esc_textarea((string)($item['resolution_note']??'')).'</textarea><span class="description">'.esc_html($knowledge?'Required before publishing. Do not copy unverified customer claims.':'Internal review only. This text will not be added to the Knowledge Base.').'</span></label><label><strong>'.($knowledge?'Source URL':'Reference URL').' (optional)</strong><input class="widefat" type="url" name="knowledge_source_url" value="'.esc_attr((string)($item['knowledge_source_url']??'')).'"></label><div class="orion-gap-actions">';if(!Orion_Manager_Queue_Policy::is_terminal($status)){echo '<button class="button" name="gap_action" value="save">Save review</button>';if($knowledge)echo '<button class="button button-primary" name="gap_action" value="publish" onclick="return confirm(\'Add only this reviewed guidance to the AI Knowledge Base?\')">Add to Knowledge Base</button>';echo '<button class="button button-link-delete" name="gap_action" value="ignore">Ignore gap</button>';}else echo '<button class="button button-primary" name="gap_action" value="reopen">Reopen</button>';echo '</div></form>';}
 private function return_fields():void{$values=array('gap_page'=>max(1,absint($_GET['gap_page']??1)),'gap_per_page'=>absint($_GET['gap_per_page']??10),'gap_status'=>sanitize_key(wp_unslash($_GET['gap_status']??'')),'gap_reason'=>sanitize_key(wp_unslash($_GET['gap_reason']??'')),'gap_type'=>sanitize_key(wp_unslash($_GET['gap_type']??'')),'gap_group'=>absint($_GET['gap_group']??0));foreach($values as$key=>$value)echo '<input type="hidden" name="return_'.esc_attr($key).'" value="'.esc_attr((string)$value).'">';}
 public function handle_ticket():void{if(!current_user_can('manage_woocommerce'))wp_die('Forbidden');$group_id=absint($_POST['group_id']??0);check_admin_referer('orion_ai_update_improvement_ticket_'.$group_id);$owner=absint($_POST['ticket_owner_id']??0);if($owner){$user=get_userdata($owner);if(!$user||!user_can($user,'manage_woocommerce'))$owner=0;}$ok=$this->gaps->save_ticket($group_id,array('title'=>wp_unslash($_POST['ticket_title']??''),'status'=>wp_unslash($_POST['ticket_status']??''),'priority'=>wp_unslash($_POST['ticket_priority']??''),'owner_id'=>$owner,'plan'=>wp_unslash($_POST['ticket_plan']??''),'verification'=>wp_unslash($_POST['ticket_verification']??''),'reference_url'=>wp_unslash($_POST['ticket_reference_url']??'')),get_current_user_id());$message=$ok?'Improvement ticket saved.':'Ticket was not saved. Check the workflow transition, title, fix plan and resolution evidence.';wp_safe_redirect(add_query_arg(array('page'=>'orion-ai-assistant','tab'=>'gaps','gap_group'=>$group_id,'orion_notice'=>$message),admin_url('admin.php')));exit;}
 public function handle_update():void{if(!current_user_can('manage_woocommerce'))wp_die('Forbidden');$id=absint($_POST['gap_id']??0);check_admin_referer('orion_ai_update_gap_'.$id);$item=$this->gaps->get($id);if(!$item)$this->redirect('Improvement gap was not found.');$type=Orion_Improvement_Ticket_Policy::normalize((string)($item['gap_type']??''));$action=sanitize_key(wp_unslash($_POST['gap_action']??'save'));$title=mb_substr(sanitize_text_field(wp_unslash($_POST['knowledge_title']??'')),0,240);$guidance=mb_substr(trim(wp_kses_post(wp_unslash($_POST['verified_guidance']??''))),0,12000);$source=esc_url_raw(trim((string)wp_unslash($_POST['knowledge_source_url']??'')));$user=get_current_user_id();$conversation=(int)$item['conversation_id'];if($action==='save'){$ok=$this->gaps->save_review($id,$title,$guidance,$source,$user);if($ok)$this->conversations->record_event('improvement_gap_reviewed',array('gap_id'=>$id,'gap_type'=>$type,'actor_user_id'=>$user),$conversation);$this->redirect($ok?'Improvement review saved.':'The review could not be saved.');}if($action==='publish'){if(!Orion_Improvement_Ticket_Policy::can_publish_to_knowledge($type))$this->redirect('Only Knowledge Base gaps can publish guidance. Fix this gap in the recommended source system.');if($title===''||mb_strlen(trim(wp_strip_all_tags($guidance)))<20)$this->redirect('Enter a knowledge title and at least 20 characters of verified guidance.');if(!$this->gaps->save_review($id,$title,$guidance,$source,$user))$this->redirect('The review could not be saved.');$markdown=$guidance;if($source!=='')$markdown.="\n\nSource: [".$source."](".$source.")";$result=$this->knowledge->create_manual($title,$markdown);if(empty($result['ok']))$this->redirect((string)$result['message']);$document_id=0;$hash=hash('sha256',wp_kses_post(wp_unslash($markdown)));foreach($this->knowledge->all()as$document)if((string)$document['title']===$title&&(string)$document['content_hash']===$hash){$document_id=(int)$document['id'];break;}if(!$document_id||!$this->gaps->mark_knowledge_added($id,$document_id,$user)){if($document_id)$this->knowledge->delete_document($document_id);$this->redirect('Knowledge was indexed but the gap could not be linked; the temporary document was removed.');}$this->conversations->record_event('knowledge_gap_published',array('gap_id'=>$id,'gap_type'=>$type,'document_id'=>$document_id,'actor_user_id'=>$user),$conversation);$this->redirect('Verified guidance added and indexed in the Knowledge Base.');}if($action==='ignore'){$ok=$this->gaps->transition($id,Orion_Manager_Queue_Policy::STATUS_DISMISSED,$user);if($ok)$this->conversations->record_event('improvement_gap_ignored',array('gap_id'=>$id,'gap_type'=>$type,'actor_user_id'=>$user),$conversation);$this->redirect($ok?'Improvement gap ignored.':'The gap could not be ignored.');}if($action==='reopen'){$ok=$this->gaps->transition($id,Orion_Manager_Queue_Policy::STATUS_NEW,$user);$this->redirect($ok?'Improvement gap reopened.':'The gap could not be reopened.');}$this->redirect('Unknown action.');}
 private function history(int $id):void{$history=$this->gaps->history($id,30);if(!$history)return;echo '<details><summary>Review history</summary><ul>';foreach($history as$event){$uid=absint($event['user_id']??0);$user=$uid?get_userdata($uid):false;$actor=$user?$user->display_name:($uid?'User #'.$uid:'System');echo '<li><strong>'.esc_html(str_replace('_',' ',(string)$event['event_type'])).'</strong> · '.esc_html($actor).' · '.esc_html((string)$event['created_at']).'</li>';}echo '</ul></details>';}
 private function redirect(string $message):void{$args=array('page'=>'orion-ai-assistant','tab'=>'gaps','orion_notice'=>$message);$page=max(1,absint($_POST['return_gap_page']??1));$per_page=absint($_POST['return_gap_per_page']??10);if($page>1)$args['gap_page']=$page;if(in_array($per_page,array(20,50),true))$args['gap_per_page']=$per_page;$status=sanitize_key(wp_unslash($_POST['return_gap_status']??''));$reason=sanitize_key(wp_unslash($_POST['return_gap_reason']??''));$type=sanitize_key(wp_unslash($_POST['return_gap_type']??''));$group=absint($_POST['return_gap_group']??0);if(Orion_Manager_Queue_Policy::is_status($status))$args['gap_status']=$status;if($reason!=='')$args['gap_reason']=$reason;if(in_array($type,Orion_Improvement_Ticket_Policy::types(),true))$args['gap_type']=$type;if($group)$args['gap_group']=$group;wp_safe_redirect(add_query_arg($args,admin_url('admin.php')));exit;}
 private function status_label(string $status):string{return array('new'=>'New','in_progress'=>'Reviewing','resolved'=>'Added to knowledge','dismissed'=>'Ignored')[$status]??ucwords(str_replace('_',' ',$status));}
}
